using System.ComponentModel;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

/// <summary>
/// MCP tool that fetches data from an external API using an injected HttpClient.
/// </summary>
internal class ApiFetchTool(HttpClient httpClient, ILogger<ApiFetchTool> logger)
{
    [McpServerTool(Name = "fetch_api")]
    [Description("Fetches data from a public API endpoint and returns the response body as text.")]
    public async Task<string> FetchApiAsync(
        [Description("The full URL to fetch (e.g. https://api.example.com/data)")] string url,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching URL: {Url}", url);

        using var response = await httpClient.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();

        var body = await response.Content.ReadAsStringAsync(cancellationToken);
        logger.LogInformation("Received {Length} characters from {Url}", body.Length, url);

        return body;
    }
}

using System.ComponentModel;
using ModelContextProtocol;
using ModelContextProtocol.Server;

/// <summary>
/// MCP prompt template that produces a summarization request.
/// </summary>
internal class SummarizationPrompt
{
    [McpServerPrompt(Name = "summarize")]
    [Description("Generates a prompt that asks the model to summarize the provided text.")]
    public static ChatMessage[] Summarize(
        [Description("The text to summarize")] string text,
        [Description("Optional maximum number of sentences for the summary")] int maxSentences = 3)
    {
        return
        [
            new(ChatRole.User,
                $"Summarize the following text in at most {maxSentences} sentences. " +
                $"Be concise and capture the key points.\n\n{text}")
        ];
    }
}

